// Script177 helpers.
//
// Diagnostic hypothesis generated by Script176:
// Script161 observedWeaponState.clip (Source2 m_iClip) appears to carry a
// signed ZigZag-decoded representation of a non-negative internal clip code.
//
// Pre-registered candidate transform:
//   raw >= 0 ? 2 * raw : -2 * raw - 1
//
// This module tests the transform empirically. It does not promote the
// transformed value as gameplay ammunition or effective magazine capacity.

export function zigzagReencode(raw) {
  if (!Number.isFinite(raw)) return null;
  return raw >= 0
    ? 2 * raw
    : -2 * raw - 1;
}

export function normalizeClipEvent(row, index = 0) {
  const observed = row?.observedWeaponState ?? {};

  const rawClip = finite(firstDefined(
    observed?.clip,
    deepFindExactKey(row, 'clip'),
    deepFindExactKey(row, 'm_iClip'),
  ));

  return {
    sourceIndex: index,
    tick: finite(firstDefined(
      row?.tick,
      row?.demoTick,
      deepFindExactKey(row, 'tick'),
    )),
    heroId: finite(firstDefined(
      row?.heroId,
      deepFindExactKey(row, 'heroId'),
    )),
    playerKey: stringOrNull(firstDefined(
      row?.playerKey,
      row?.playerName,
      deepFindExactKey(row, 'playerKey'),
      deepFindExactKey(row, 'playerName'),
    )),
    weaponEntityIndex: finite(firstDefined(
      row?.weaponEntityIndex,
      deepFindExactKey(row, 'weaponEntityIndex'),
    )),
    effectContextId: stringOrNull(firstDefined(
      row?.effectContextId,
      deepFindExactKey(row, 'effectContextId'),
    )) ?? 'NO_EFFECT_CONTEXT_ID',
    activeFireMode: finite(firstDefined(
      observed?.activeFireMode,
      deepFindExactKey(row, 'activeFireMode'),
      deepFindExactKey(row, 'm_eActiveFireMode'),
    )) ?? 0,

    rawClip,
    transformedClip: zigzagReencode(rawClip),

    bonusClip: finite(firstDefined(
      observed?.bonusClip,
      deepFindExactKey(row, 'bonusClip'),
      deepFindExactKey(row, 'm_iBonusClip'),
    )),
    ammoFraction: finite(firstDefined(
      observed?.ammoFraction,
      deepFindExactKey(row, 'ammoFraction'),
      deepFindExactKey(row, 'm_flAmmoFrac'),
    )),
    inReload: booleanOrNull(firstDefined(
      observed?.inReload,
      deepFindExactKey(row, 'inReload'),
      deepFindExactKey(row, 'm_bInReload'),
    )),
    shotNumber: finite(firstDefined(
      observed?.shotNumber,
      deepFindExactKey(row, 'shotNumber'),
      deepFindExactKey(row, 'm_nShotNumber'),
    )),
    lastAttackTime: finite(firstDefined(
      observed?.lastAttackTime,
      deepFindExactKey(row, 'lastAttackTime'),
      deepFindExactKey(row, 'm_flLastAttackTime'),
    )),
  };
}

export function groupClipEvents(events) {
  const map = new Map();

  for (const event of events) {
    const key = contextKey(event);

    if (!map.has(key)) {
      map.set(key, []);
    }

    map.get(key).push(event);
  }

  for (const rows of map.values()) {
    rows.sort(
      (a, b) =>
        a.tick - b.tick
        || a.sourceIndex - b.sourceIndex,
    );
  }

  return map;
}

export function diagnoseShotTransitions(events) {
  const rows = [];

  for (let index = 1; index < events.length; index++) {
    const previous = events[index - 1];
    const current = events[index];

    if (
      previous.inReload === true
      || current.inReload === true
      || !Number.isFinite(previous.shotNumber)
      || !Number.isFinite(current.shotNumber)
      || !Number.isFinite(previous.rawClip)
      || !Number.isFinite(current.rawClip)
      || !Number.isFinite(previous.transformedClip)
      || !Number.isFinite(current.transformedClip)
    ) {
      continue;
    }

    const shotAdvance =
      current.shotNumber - previous.shotNumber;

    if (shotAdvance <= 0) continue;

    const rawDrop =
      previous.rawClip - current.rawClip;

    const absDrop =
      Math.abs(previous.rawClip)
      - Math.abs(current.rawClip);

    const transformedDrop =
      previous.transformedClip
      - current.transformedClip;

    rows.push({
      tick: current.tick,
      shotAdvance,
      previousRawClip: previous.rawClip,
      currentRawClip: current.rawClip,
      previousTransformedClip:
        previous.transformedClip,
      currentTransformedClip:
        current.transformedClip,

      rawDrop,
      rawDropPerShot:
        rawDrop / shotAdvance,

      absDrop,
      absDropPerShot:
        absDrop / shotAdvance,

      transformedDrop,
      transformedDropPerShot:
        transformedDrop / shotAdvance,

      transformedPositiveIntegerPerShot:
        transformedDrop > 0
        && Number.isInteger(
          transformedDrop / shotAdvance,
        ),
    });
  }

  return summarizeTransitionRows(rows);
}

export function summarizeTransitionRows(rows) {
  const transformedValues =
    rows.map(row => row.transformedDropPerShot);

  const rawValues =
    rows.map(row => row.rawDropPerShot);

  const absValues =
    rows.map(row => row.absDropPerShot);

  const transformedMode =
    uniqueMode(transformedValues);

  const rawMode =
    uniqueMode(rawValues);

  const absMode =
    uniqueMode(absValues);

  return {
    observations: rows.length,
    rows,

    transformed: {
      positiveIntegerPerShot:
        rows.filter(
          row =>
            row.transformedPositiveIntegerPerShot,
        ).length,
      positiveIntegerPerShotRate:
        rows.length > 0
          ? rows.filter(
            row =>
              row.transformedPositiveIntegerPerShot,
          ).length / rows.length
          : null,
      mode:
        transformedMode?.value ?? null,
      modeCount:
        transformedMode?.count ?? 0,
      modeDominance:
        rows.length > 0
          && transformedMode
          ? transformedMode.count / rows.length
          : null,
      median: median(transformedValues),
      unique:
        uniqueSorted(transformedValues),
    },

    raw: {
      mode:
        rawMode?.value ?? null,
      modeDominance:
        rows.length > 0 && rawMode
          ? rawMode.count / rows.length
          : null,
      median: median(rawValues),
      negativeRate:
        rows.length > 0
          ? rows.filter(
            row => row.rawDropPerShot < 0,
          ).length / rows.length
          : null,
      uniqueCount:
        new Set(
          rawValues.map(round6),
        ).size,
    },

    absoluteValue: {
      mode:
        absMode?.value ?? null,
      modeDominance:
        rows.length > 0 && absMode
          ? absMode.count / rows.length
          : null,
      median: median(absValues),
      negativeRate:
        rows.length > 0
          ? rows.filter(
            row => row.absDropPerShot < 0,
          ).length / rows.length
          : null,
      uniqueCount:
        new Set(
          absValues.map(round6),
        ).size,
    },
  };
}

export function diagnoseClipSignPattern(events) {
  const clipRows =
    events.filter(
      row => Number.isFinite(row.rawClip),
    );

  const negatives =
    clipRows.filter(row => row.rawClip < 0).length;
  const zeros =
    clipRows.filter(row => row.rawClip === 0).length;
  const positives =
    clipRows.filter(row => row.rawClip > 0).length;

  let alternatingAdjacent = 0;
  let signComparableAdjacent = 0;

  for (let index = 1; index < clipRows.length; index++) {
    const a = clipRows[index - 1].rawClip;
    const b = clipRows[index].rawClip;

    if (a === 0 || b === 0) continue;

    signComparableAdjacent++;

    if (Math.sign(a) !== Math.sign(b)) {
      alternatingAdjacent++;
    }
  }

  return {
    clipRows: clipRows.length,
    negative: negatives,
    zero: zeros,
    positive: positives,
    negativeRate:
      clipRows.length > 0
        ? negatives / clipRows.length
        : null,
    signComparableAdjacent,
    alternatingAdjacent,
    alternatingAdjacentRate:
      signComparableAdjacent > 0
        ? alternatingAdjacent
          / signComparableAdjacent
        : null,
    rawMin:
      clipRows.length > 0
        ? Math.min(
          ...clipRows.map(row => row.rawClip),
        )
        : null,
    rawMax:
      clipRows.length > 0
        ? Math.max(
          ...clipRows.map(row => row.rawClip),
        )
        : null,
    transformedMin:
      clipRows.length > 0
        ? Math.min(
          ...clipRows.map(
            row => row.transformedClip,
          ),
        )
        : null,
    transformedMax:
      clipRows.length > 0
        ? Math.max(
          ...clipRows.map(
            row => row.transformedClip,
          ),
        )
        : null,
  };
}

export function transformScript174Candidates(script174) {
  const contexts =
    script174?.evaluation?.contexts ?? [];

  return contexts
    .filter(
      row =>
        row?.primaryEligible === true
        && Number.isFinite(row?.candidateCapacity),
    )
    .map(row => ({
      contextKey: row.contextKey,
      heroId: finite(row.heroId),
      rawCandidate:
        finite(row.candidateCapacity),
      transformedCandidate:
        zigzagReencode(
          finite(row.candidateCapacity),
        ),
      staticClipSize:
        finite(row.staticClipSize),
      completionLikeReloads:
        finite(row.completionLikeReloads) ?? 0,
      contextPass:
        row.contextPass === true,
    }));
}

export function extractStaticWeaponAmmoProfiles(script165) {
  const profiles = new Map();

  walk(script165, value => {
    if (
      !value
      || typeof value !== 'object'
      || Array.isArray(value)
    ) {
      return;
    }

    const heroId =
      finite(value.heroId);

    if (heroId === null) return;

    const clipSize =
      finite(firstDefined(
        value.clipSize,
        value.staticClipSize,
        deepFindExactKey(
          value,
          'm_iClipSize',
        ),
      ));

    const ammoConsumed =
      finite(firstDefined(
        value.ammoConsumedPerShot,
        value.staticAmmoConsumedPerShot,
        deepFindExactKey(
          value,
          'm_iAmmoConsumedPerShot',
        ),
      ));

    if (
      clipSize === null
      && ammoConsumed === null
    ) {
      return;
    }

    const prior =
      profiles.get(heroId) ?? {
        heroId,
        displayName:
          stringOrNull(
            value.displayName,
          ),
        staticClipSize: null,
        ammoConsumedPerShot: null,
      };

    if (
      prior.staticClipSize === null
      && clipSize !== null
    ) {
      prior.staticClipSize =
        clipSize;
    }

    if (
      prior.ammoConsumedPerShot === null
      && ammoConsumed !== null
    ) {
      prior.ammoConsumedPerShot =
        ammoConsumed;
    }

    profiles.set(heroId, prior);
  });

  return profiles;
}

export function compareHeroTransformToStatic(
  candidateRows,
  transitionByContext,
  staticProfiles,
) {
  const heroMap = new Map();

  for (const candidate of candidateRows) {
    const heroId = candidate.heroId;

    if (!heroMap.has(heroId)) {
      heroMap.set(heroId, {
        heroId,
        transformedCandidates: [],
        rawCandidates: [],
        contextShotModes: [],
      });
    }

    const hero = heroMap.get(heroId);

    hero.transformedCandidates.push(
      candidate.transformedCandidate,
    );
    hero.rawCandidates.push(
      candidate.rawCandidate,
    );

    const transition =
      transitionByContext.get(
        candidate.contextKey,
      );

    if (
      Number.isFinite(
        transition?.transformed?.mode,
      )
    ) {
      hero.contextShotModes.push(
        transition.transformed.mode,
      );
    }
  }

  return [...heroMap.values()]
    .map(hero => {
      const staticProfile =
        staticProfiles.get(hero.heroId)
        ?? null;

      const minTransformedCandidate =
        minFinite(
          hero.transformedCandidates,
        );

      const modalShotConsumption =
        uniqueMode(
          hero.contextShotModes,
        )?.value ?? null;

      return {
        heroId: hero.heroId,
        rawCandidates:
          uniqueSorted(hero.rawCandidates),
        transformedCandidates:
          uniqueSorted(
            hero.transformedCandidates,
          ),
        minTransformedCandidate,
        modalShotConsumption,
        staticClipSize:
          staticProfile?.staticClipSize
          ?? null,
        staticAmmoConsumedPerShot:
          staticProfile
            ?.ammoConsumedPerShot
          ?? null,

        minCandidateMinusStatic:
          Number.isFinite(
            minTransformedCandidate,
          )
          && Number.isFinite(
            staticProfile?.staticClipSize,
          )
            ? minTransformedCandidate
              - staticProfile.staticClipSize
            : null,

        minCandidateMinusObservedShotConsumption:
          Number.isFinite(
            minTransformedCandidate,
          )
          && Number.isFinite(
            modalShotConsumption,
          )
            ? minTransformedCandidate
              - modalShotConsumption
            : null,

        correctedBaseComparison:
          Number.isFinite(
            minTransformedCandidate,
          )
          && Number.isFinite(
            modalShotConsumption,
          )
          && Number.isFinite(
            staticProfile?.staticClipSize,
          )
            ? (
              minTransformedCandidate
              - modalShotConsumption
            ) - staticProfile.staticClipSize
            : null,
      };
    })
    .sort(
      (a, b) =>
        (a.heroId ?? 0)
        - (b.heroId ?? 0),
    );
}

export function transformedOvershootPhase(
  candidate,
  events,
) {
  const transformedCandidate =
    candidate.transformedCandidate;

  let firstReloadExitTick = null;
  let previous = null;

  for (const row of events) {
    if (
      previous
      && previous.inReload === true
      && row.inReload === false
    ) {
      firstReloadExitTick = row.tick;
      break;
    }

    previous = row;
  }

  const overshoots =
    events.filter(
      row =>
        Number.isFinite(
          row.transformedClip,
        )
        && Number.isFinite(
          transformedCandidate,
        )
        && row.transformedClip
          > transformedCandidate,
    );

  const beforeFirstReload =
    firstReloadExitTick === null
      ? overshoots.length
      : overshoots.filter(
        row =>
          row.tick < firstReloadExitTick,
      ).length;

  const atOrAfterFirstReload =
    firstReloadExitTick === null
      ? 0
      : overshoots.filter(
        row =>
          row.tick >= firstReloadExitTick,
      ).length;

  return {
    contextKey: candidate.contextKey,
    heroId: candidate.heroId,
    transformedCandidate,
    firstReloadExitTick,
    overshoots: overshoots.length,
    beforeFirstReload,
    atOrAfterFirstReload,
  };
}

function contextKey(event) {
  return [
    event.playerKey
      ?? 'UNKNOWN_PLAYER',
    event.weaponEntityIndex
      ?? 'UNKNOWN_WEAPON',
    event.effectContextId
      ?? 'NO_EFFECT_CONTEXT_ID',
    event.activeFireMode ?? 0,
  ].join('|');
}

function uniqueMode(values) {
  const counts = new Map();

  for (
    const value
    of values.filter(Number.isFinite)
  ) {
    const key = round6(value);

    counts.set(
      key,
      (counts.get(key) ?? 0) + 1,
    );
  }

  if (counts.size === 0) return null;

  const ordered =
    [...counts.entries()]
      .sort(
        (a, b) =>
          b[1] - a[1]
          || a[0] - b[0],
      );

  if (
    ordered.length > 1
    && ordered[0][1] === ordered[1][1]
  ) {
    return null;
  }

  return {
    value: ordered[0][0],
    count: ordered[0][1],
  };
}

function median(values) {
  const sorted =
    values
      .filter(Number.isFinite)
      .sort((a, b) => a - b);

  if (sorted.length === 0) {
    return null;
  }

  const middle =
    Math.floor(
      sorted.length / 2,
    );

  return sorted.length % 2
    ? sorted[middle]
    : (
      sorted[middle - 1]
      + sorted[middle]
    ) / 2;
}

function uniqueSorted(values) {
  return [
    ...new Set(
      values
        .filter(Number.isFinite)
        .map(round6),
    ),
  ].sort((a, b) => a - b);
}

function minFinite(values) {
  const finite =
    values.filter(Number.isFinite);

  return finite.length
    ? Math.min(...finite)
    : null;
}

function round6(value) {
  return Number(
    Number(value).toFixed(6),
  );
}

export function deepFindExactKey(
  root,
  key,
  maxDepth = 8,
) {
  if (
    !root
    || typeof root !== 'object'
  ) {
    return undefined;
  }

  const seen = new Set();
  const queue = [
    { value: root, depth: 0 },
  ];

  while (queue.length) {
    const { value, depth } =
      queue.shift();

    if (
      !value
      || typeof value !== 'object'
      || seen.has(value)
      || depth > maxDepth
    ) {
      continue;
    }

    seen.add(value);

    if (
      !Array.isArray(value)
      && Object.prototype.hasOwnProperty.call(
        value,
        key,
      )
    ) {
      return value[key];
    }

    for (
      const child
      of (
        Array.isArray(value)
          ? value
          : Object.values(value)
      )
    ) {
      if (
        child
        && typeof child === 'object'
      ) {
        queue.push({
          value: child,
          depth: depth + 1,
        });
      }
    }
  }

  return undefined;
}

function walk(root, visitor, maxDepth = 10) {
  const seen = new Set();

  function visit(value, depth) {
    if (
      !value
      || typeof value !== 'object'
      || seen.has(value)
      || depth > maxDepth
    ) {
      return;
    }

    seen.add(value);
    visitor(value);

    for (const child of Object.values(value)) {
      visit(
        child,
        depth + 1,
      );
    }
  }

  visit(root, 0);
}

function firstDefined(...values) {
  return values.find(
    value =>
      value !== undefined
      && value !== null,
  );
}

function finite(value) {
  if (
    value === null
    || value === undefined
    || value === ''
  ) {
    return null;
  }

  const number = Number(value);

  return Number.isFinite(number)
    ? number
    : null;
}

function booleanOrNull(value) {
  if (
    value === true
    || value === false
  ) {
    return value;
  }

  if (
    value === 1
    || value === '1'
    || value === 'true'
  ) {
    return true;
  }

  if (
    value === 0
    || value === '0'
    || value === 'false'
  ) {
    return false;
  }

  return null;
}

function stringOrNull(value) {
  if (
    value === null
    || value === undefined
  ) {
    return null;
  }

  const text = String(value);

  return text.length > 0
    ? text
    : null;
}
